-- ============================================================
-- STO Management — Sample Data for Analytics Dashboard
-- ============================================================
-- Run this in SSMS against your sto_management database.
-- All rows use STO IDs prefixed 'STO-DEMO-' so they won't
-- clash with data from npm run seed.
--
-- To remove this data later:
--   DELETE FROM sto_audit_log  WHERE sto_request_id IN (SELECT id FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%');
--   DELETE FROM sto_requests   WHERE sto_id LIKE 'STO-DEMO-%';
-- ============================================================

-- Covers:
--   • 12 months of data  (Jun 2025 → May 2026)
--   • 3 sites            (ABC, ABL, XYZ)
--   • All 8 statuses
--   • ~25% rush requests
--   • Varied material values ($2K–$52K)
--   • 6 different site-to-site routes
-- ============================================================


