-- ============================================================
-- Audit log entries for all sample STOs
-- (Only key lifecycle events — CREATED + final status change)
-- ============================================================

INSERT INTO sto_audit_log (sto_request_id, action, old_status, new_status, performed_by, performed_by_name, notes, performed_at)
SELECT id, 'CREATED', NULL, 'DRAFT', requestor_user_id, requestor_name, NULL, request_date
FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%';

INSERT INTO sto_audit_log (sto_request_id, action, old_status, new_status, performed_by, performed_by_name, notes, performed_at)
SELECT id, 'SUBMITTED', 'DRAFT', 'PLANNING_REVIEW', requestor_user_id, requestor_name, NULL, DATEADD(day, 1, request_date)
FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%' AND status <> 'DRAFT';

INSERT INTO sto_audit_log (sto_request_id, action, old_status, new_status, performed_by, performed_by_name, notes, performed_at)
SELECT id, 'PLANNING_APPROVED', 'PLANNING_REVIEW', 'SHIPPING_LOGISTICS', planning_approved_by_user_id, 'Shipping Site Planning', planning_notes, planning_approved_at
FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%' AND planning_approved = 1;

INSERT INTO sto_audit_log (sto_request_id, action, old_status, new_status, performed_by, performed_by_name, notes, performed_at)
SELECT id, 'PLANNING_REJECTED', 'PLANNING_REVIEW', 'REJECTED', planning_approved_by_user_id, 'Shipping Site Planning', rejection_reason, planning_approved_at
FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%' AND planning_approved = 0 AND status = 'REJECTED';

INSERT INTO sto_audit_log (sto_request_id, action, old_status, new_status, performed_by, performed_by_name, notes, performed_at)
SELECT id, 'FINANCE_APPROVED', 'FINANCE_REVIEW', 'RECEIVING_LOGISTICS', finance_approved_by_user_id, 'Finance', finance_notes, finance_approved_at
FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%' AND finance_approved = 1;

INSERT INTO sto_audit_log (sto_request_id, action, old_status, new_status, performed_by, performed_by_name, notes, performed_at)
SELECT id, 'DELIVERY_CLOSED', 'RECEIVING_LOGISTICS', 'CLOSED', requestor_user_id, 'Receiving Site Logistics', 'Delivery confirmed and closed.', actual_receipt_date
FROM sto_requests WHERE sto_id LIKE 'STO-DEMO-%' AND status = 'CLOSED';


